module multi_pipe_8bit(
    input clk, 
    input rst_n, 
    input mul_en_in,
    output reg mul_en_out,
    input [7:0] mul_a,
    input [7:0] mul_b,
    output reg [15:0] mul_out
);
    // Internal signals
    reg [1:0] mul_en_out_reg;
    wire [15:0] temp[0:7];
    reg [7:0] mul_a_reg;
    reg [7:0] mul_b_reg;
    reg [15:0] sum[0:3];
    reg [15:0] mul_out_reg;

    // Sequential logic for updating mul_en_out_reg
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_en_out_reg <= 2'b0;
        end else begin
            mul_en_out_reg <= {mul_en_out_reg[0], mul_en_in};
        end
    end

    // Generate partial products
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : pp_gen
            assign temp[i][15:0] = ({8{mul_b_reg[i]}} & mul_a_reg);
        end
    endgenerate

    // Sequential logic for calculating partial sums
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum[0] <= 16'd0;
            sum[1] <= 16'd0;
            sum[2] <= 16'd0;
            sum[3] <= 16'd0;
        end else begin
            case (mul_en_out_reg)
                2'b01: begin
                    sum[0] <= temp[0];
                    sum[1] <= temp[1] + temp[2];
                    sum[2] <= temp[3] + temp[4];
                    sum[3] <= temp[5] + temp[6];
                end

                2'b10: begin
                    sum[0] <= temp[0];
                    sum[1] <= temp[1] + temp[2];
                    sum[2] <= temp[3] + temp[4];
                    sum[3] <= temp[5] + temp[6];
                end

                default: begin
                    sum[0] <= 16'd0;
                    sum[1] <= 16'd0;
                    sum[2] <= 16'd0;
                    sum[3] <= 16'd0;
                end
            endcase
        end
    end

    // Sequential logic for calculating final product
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out_reg <= 16'd0;
        end else begin
            mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
        end
    end

    // Assigning output
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out <= 16'd0;
        end else begin
            mul_out <= (mul_en_out_reg[1]) ? mul_out_reg : 16'd0;
        end
    end

    // Register to hold the multiplicand
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_a_reg <= 8'd0;
        end else if (mul_en_in) begin
            mul_a_reg <= mul_a;
        end
    end

    // Register to hold the multiplier
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_b_reg <= 8'd0;
        end else if (mul_en_in) begin
            mul_b_reg <= mul_b;
        end
    end
endmodule
